var player=UnityEngine.Object.FindFirstObjectByType<IndianOceanAssets.ShooterSurvival.PlayerScript>();
var flags=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.Public|System.Reflection.BindingFlags.NonPublic;
return new{player.moveSensitivity,player.moveSensitivity_Devision,smoothness=typeof(IndianOceanAssets.ShooterSurvival.PlayerScript).GetField("movementSmoothness",flags).GetValue(player),playerScale=player.transform.lossyScale.ToString(),colliders=player.GetComponentsInChildren<UnityEngine.Collider>().Select(c=>new{c.name,size=c.bounds.size.ToString(),c.isTrigger}).ToArray(),laneRange=typeof(IndianOceanAssets.ShooterSurvival.PlayerScript).GetField("xRange",flags).GetValue(player)?.ToString(),fields=typeof(IndianOceanAssets.ShooterSurvival.PlayerScript).GetFields(flags).Where(f=>f.Name.ToLowerInvariant().Contains("speed")).Select(f=>new{f.Name,value=f.GetValue(player)?.ToString()}).ToArray()};
